PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,kind TEXT NOT NULL,access TEXT UNIQUE,refresh TEXT UNIQUE,csrf TEXT,access_until REAL NOT NULL,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS tokens(hash TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,kind TEXT NOT NULL,expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id INTEGER PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,payload TEXT NOT NULL,next_try REAL NOT NULL,attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS devices(id TEXT PRIMARY KEY,secret TEXT NOT NULL,metadata TEXT NOT NULL,account TEXT REFERENCES accounts,ownership TEXT,name TEXT NOT NULL,retired INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS claims(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,device TEXT NOT NULL,nonce TEXT NOT NULL,expires REAL NOT NULL,proof TEXT,result TEXT);
CREATE TABLE IF NOT EXISTS rigs(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(device TEXT PRIMARY KEY REFERENCES devices,rig TEXT NOT NULL REFERENCES rigs ON DELETE CASCADE,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,start TEXT NOT NULL,started REAL NOT NULL,rig TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'recording',completion TEXT,UNIQUE(account,id));
CREATE INDEX IF NOT EXISTS sessions_time ON sessions(account,started DESC,id);
CREATE TABLE IF NOT EXISTS records(id INTEGER PRIMARY KEY,account TEXT NOT NULL,session TEXT NOT NULL,kind TEXT NOT NULL,key TEXT NOT NULL,data TEXT NOT NULL,device TEXT,at REAL,role TEXT,pa INTEGER,lat REAL,lon REAL,eligible INTEGER,speed REAL,UNIQUE(kind,key),FOREIGN KEY(account,session) REFERENCES sessions(account,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS records_session ON records(account,session,kind,at,id);
CREATE INDEX IF NOT EXISTS records_time ON records(account,kind,at);
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,account TEXT NOT NULL,session TEXT NOT NULL,hash TEXT NOT NULL,receipt TEXT NOT NULL,FOREIGN KEY(account,session) REFERENCES sessions(account,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS leases(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,collector TEXT NOT NULL,devices TEXT NOT NULL,session TEXT,expires REAL NOT NULL,seq INTEGER NOT NULL DEFAULT -1,UNIQUE(account,collector));
CREATE TABLE IF NOT EXISTS presence(device TEXT PRIMARY KEY REFERENCES devices,account TEXT NOT NULL REFERENCES accounts ON DELETE CASCADE,lease TEXT NOT NULL,observed REAL NOT NULL,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
PRAGMA user_version=1;

CREATE INDEX IF NOT EXISTS records_device ON records(account,device,kind,at DESC);
